// Newsletter page: subject and preheader (MJML only: an uploaded HTML is never altered) edited in place. Double-click (or Enter / F2 when focused) turns the
// text into a field; Enter or leaving the field saves, Escape cancels. Saved without creating a new version
// (POST {subject, preheader} to data-header-url). An empty preheader becomes automatic again (generated by the server).
(function () {
    'use strict';
    var box = document.querySelector('[data-header-url]');
    if (!box || !window.fetch) return;
    var t = window.CalageLang.t;
    var subject = box.querySelector('[data-edit="subject"]');
    var preheader = box.querySelector('[data-edit="preheader"]');
    var saving = false;

    function show(el, text) {
        el.textContent = '';
        if (text === '') {
            var empty = document.createElement('span');
            empty.className = 'not-set';
            empty.textContent = el.getAttribute('data-placeholder');
            el.appendChild(empty);
        } else {
            el.textContent = text;
        }
    }

    function edit(el) {
        if (el.querySelector('input') || saving) return;
        var shown = el.querySelector('.not-set') ? '' : el.textContent;
        var input = document.createElement('input');
        input.type = 'text';
        input.className = 'inline-edit';
        input.maxLength = Number(el.getAttribute('data-max')) || 250;
        input.value = el.getAttribute('data-value');
        // Automatic preheader: the field starts empty, the generated text is the placeholder.
        input.placeholder = el.getAttribute('data-auto') === '1' && shown !== '' ? t('Automatic: {text}', { text: shown }) : el.getAttribute('data-placeholder');
        input.setAttribute('aria-label', el === subject ? t('Subject') : t('Preheader'));
        el.textContent = '';
        el.appendChild(input);
        input.focus();
        input.select();

        var done = false;
        function finish(save) {
            if (done) return;
            done = true;
            if (!save || input.value.trim() === el.getAttribute('data-value')) {
                show(el, shown);
                el.focus();
                return;
            }
            send(el, input.value.trim(), shown);
        }
        input.addEventListener('keydown', function (e) {
            if (e.key === 'Enter') { e.preventDefault(); finish(true); }
            if (e.key === 'Escape') { e.preventDefault(); finish(false); }
        });
        input.addEventListener('blur', function () { finish(true); });
    }

    function send(el, value, previous) {
        saving = true;
        show(el, value === '' && el === preheader ? previous : value);
        el.classList.add('is-saving');
        var body = {
            subject: el === subject ? value : subject.getAttribute('data-value'),
            // HTML newsletter: no preheader to edit (read from the code); the server keeps it as it is.
            preheader: el === preheader ? value : (preheader ? preheader.getAttribute('data-value') : '')
        };
        fetch(box.getAttribute('data-header-url'), {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': box.getAttribute('data-csrf'), 'Accept': 'application/json' },
            body: JSON.stringify(body)
        }).then(function (res) {
            return res.json().then(function (data) {
                if (!res.ok) throw new Error(data.error || String(res.status));
                return data;
            });
        }).then(function (data) {
            subject.setAttribute('data-value', data.subject);
            show(subject, data.subject);
            if (preheader) {
                preheader.setAttribute('data-value', data.preheader);
                preheader.setAttribute('data-auto', data.preheaderAuto ? '1' : '0');
                show(preheader, data.preheaderText);
                preheader.title = data.preheaderAuto
                    ? t('No preheader was entered: this is the start of the email text, as an email client shows it. Double-click to write one.')
                    : t('Double-click to edit the preheader');
            }
            // The publish form of the draft knows its subject (for the "Publish without a subject?" dialog).
            var publishSubject = document.querySelector('form[data-subject-prompt] input[name=subject]');
            if (publishSubject && box.getAttribute('data-is-draft') === '1') publishSubject.value = data.subject;
            if (window.calageToast) window.calageToast(el === subject ? t('Subject saved.') : t('Preheader saved.'));
        }).catch(function () {
            show(el, previous);
            if (window.calageToast) window.calageToast(t('Could not save. Reload the page and try again.'));
        }).then(function () {
            saving = false;
            el.classList.remove('is-saving');
        });
    }

    [subject, preheader].forEach(function (el) {
        if (!el) return;
        el.addEventListener('dblclick', function () { edit(el); });
        el.addEventListener('keydown', function (e) {
            if ((e.key === 'Enter' || e.key === 'F2') && e.target === el) { e.preventDefault(); edit(el); }
        });
    });
})();
